"""Module 08 — Voltage regulators and IC regulators (Floyd 9e Ch.17)."""
import math
from hx import *
def module(lang):
    f = lambda x, d=2: f'{x:,.{d}f}'
    K = [tr(f'Phần {i} · ' + a, f'Part {i} · ' + b) for i, a, b in ((1, 'Nền tảng', 'Foundations'), (2, 'Phương pháp', 'Methods'), (3, 'Ví dụ từ sách', 'Book examples'), (4, 'Sai lầm và mở rộng', 'Pitfalls and extensions'), (5, 'Ứng dụng và tổng kết', 'Applications and summary'))]
    v21 = 1.25 * 11 + 50e-6 * 10e3
    P = []
    s1 = sl(formula(tr('Điều chỉnh', 'Regulation'), 'Line = (ΔVOUT/ΔVIN)·100 %  ,  Load = (VNL − VFL)/VFL · 100 %') + ul([tr('Line regulation: đổi điện áp vào, điện áp ra có đứng yên không', 'Line regulation: does the output stay put when the input changes'), tr('Load regulation: đổi dòng tải, điện áp ra có đứng yên không', 'Load regulation: does the output stay put when the load current changes')]),
            K[0], tr('Hai thước đo độ ổn định', 'Two measures of regulation'), tr('Giá trị phần trăm càng nhỏ càng tốt.', 'The smaller the percentage the better.'))
    s2 = sl(table([tr('Khối', 'Block'), tr('Vai trò', 'Role')], [[tr('Tham chiếu', 'Reference'), tr('điện áp chuẩn (zener)', 'stable voltage (zener)')], [tr('Mạch lấy mẫu', 'Sampling circuit'), tr('chia điện áp ra', 'divides the output')], [tr('Bộ phát hiện sai số', 'Error detector'), tr('so sánh mẫu với tham chiếu', 'compares sample with reference')], [tr('Phần tử điều khiển', 'Control element'), tr('transistor pass', 'pass transistor')]]),
            K[0], tr('Bốn khối của bộ ổn áp', 'The four blocks of a regulator'), tr('Mọi bộ ổn áp là một vòng hồi tiếp âm: lấy mẫu → so sánh → điều khiển.', 'Every regulator is a negative-feedback loop: sample → compare → control.'))
    s3 = sl(fig('assets/figs/m08/fig17_07.png', 'series regulator', tr('Floyd Hình 17–7', 'Floyd Fig. 17–7'), 420) + formula(tr('Ổn áp nối tiếp', 'Series regulator'), 'VOUT = (1 + R2/R3)·VREF'),
            K[0], tr('Ổn áp tuyến tính nối tiếp', 'The linear series regulator'), tr('Op-amp lái transistor pass sao cho điện áp lấy mẫu bằng VREF.', 'The op-amp drives the pass transistor so the sampled voltage equals VREF.'))
    s4 = sl(fig('assets/figs/m08/fig17_15.png', 'shunt regulator', tr('Floyd Hình 17–15', 'Floyd Fig. 17–15'), 420) + ul([tr('Phần tử điều khiển mắc song song với tải', 'Control element in parallel with the load'), tr('Dòng ngắn mạch bị R1 giới hạn: IL(max) = VIN/R1', 'Short-circuit current limited by R1: IL(max) = VIN/R1')]),
            K[0], tr('Ổn áp tuyến tính song song', 'The linear shunt regulator'), tr('Đơn giản và tự bảo vệ ngắn mạch nhưng kém hiệu suất.', 'Simple and self-protected against shorts, but less efficient.'))
    P.append(dict(title=tr('Nền tảng ổn áp', 'Regulator foundations'), bullets=[tr('Line/load regulation', 'Line/load regulation'), tr('Bốn khối', 'Four blocks'), tr('Nối tiếp và song song', 'Series and shunt')], slides=[s1, s2, s3, s4]))
    s5 = sl(fig('assets/figs/m08/fig17_09.png', 'series regulator with current limiting', tr('Floyd Hình 17–9', 'Floyd Fig. 17–9'), 420) + formula(tr('Giới hạn dòng', 'Current limiting'), 'IL(max) = 0,7 V / R4'.replace('0,7', tr('0,7', '0.7'))),
            K[1], tr('Giới hạn dòng', 'Current limiting'), tr('Khi sụt áp trên R4 đạt 0,7 V, Q2 dẫn và lấy bớt dòng của Q1.', 'When the drop across R4 reaches 0.7 V, Q2 conducts and steals drive from Q1.').replace('0,7', tr('0,7', '0.7')))
    s6 = sl(fig('assets/figs/m08/fig17_17.png', 'switching regulator', tr('Floyd Hình 17–17', 'Floyd Fig. 17–17'), 520) + formula(tr('Ổn áp xung giảm áp', 'Step-down switching regulator'), 'VOUT ≈ duty × VIN  ,  duty = ton/T'),
            K[1], tr('Ổn áp xung', 'The switching regulator'), tr('Transistor đóng/ngắt hoàn toàn nên tiêu tán rất ít; bộ lọc LC lấy trung bình.', 'The transistor is fully on or off so it dissipates little; the LC filter takes the average.'))
    s7 = sl(fig('assets/figs/m08/fig17_30.png', 'LM317 adjustable regulator', tr('Floyd Hình 17–30', 'Floyd Fig. 17–30'), 440) + formula('LM317', 'VOUT = 1,25 V(1 + R2/R1) + IADJ·R2'.replace('1,25', tr('1,25', '1.25'))) + ul([tr('78XX: dương cố định; 79XX: âm cố định', '78XX: fixed positive; 79XX: fixed negative')]),
            K[1], tr('IC ổn áp: 78XX/79XX và LM317', 'IC regulators: 78XX/79XX and the LM317'), tr('Hai chữ số cuối của 78XX/79XX là điện áp ra.', 'The last two digits of a 78XX/79XX give the output voltage.'))
    s8 = sl(fig('assets/figs/m08/fig17_35.png', 'external pass transistor', tr('Floyd Hình 17–35', 'Floyd Fig. 17–35'), 520) + formula(tr('Transistor pass ngoài', 'External pass transistor'), 'Rext = 0,7 V / IREG(max)'.replace('0,7', tr('0,7', '0.7'))),
            K[1], tr('Tăng dòng bằng transistor pass ngoài', 'Boosting current with an external pass transistor'), tr('Khi sụt áp trên Rext đạt 0,7 V, Qext dẫn phần dòng dư thừa.', 'When the drop across Rext reaches 0.7 V, Qext carries the excess current.').replace('0,7', tr('0,7', '0.7')))
    P.append(dict(title=tr('Phương pháp', 'Methods'), bullets=[tr('Giới hạn dòng', 'Current limiting'), tr('Ổn áp xung', 'Switching'), tr('IC ổn áp', 'IC regulators')], slides=[s5, s6, s7, s8]))
    s9 = sl(ex(tr('Floyd Bài 1–4', 'Floyd Problems 1–4'), tr('Line = 0,0333 %; Load = 1,01 %', 'Line = 0.0333 %; Load = 1.01 %')) + ex(tr('Floyd Bài 7–9', 'Floyd Problems 7–9'), tr('(1 + 5,6/2,2)·2,4 = 8,51 V ; R3 = 4,7 kΩ → 5,26 V ; VREF = 2,7 V → 9,57 V', '(1 + 5.6/2.2)·2.4 = 8.51 V ; R3 = 4.7 kΩ → 5.26 V ; VREF = 2.7 V → 9.57 V')),
            K[2], tr('Điều chỉnh và ổn áp nối tiếp (Floyd Bài 1–9)', 'Regulation and series regulators (Floyd Problems 1–9)'), tr('Đối chiếu với đáp án sách: 0,0333 %, 1,01 %, 8,51 V, 9,57 V.', 'Matches the book: 0.0333 %, 1.01 %, 8.51 V, 9.57 V.'))
    s10 = sl(ex(tr('Floyd Bài 10–11', 'Floyd Problems 10–11'), tr('R4 = 0,7/0,25 = 2,8 Ω; P = 0,175 W; R4/2 → 500 mA', 'R4 = 0.7/0.25 = 2.8 Ω; P = 0.175 W; halving R4 → 500 mA')) + ex(tr('Floyd Bài 13, 15', 'Floyd Problems 13, 15'), tr('ΔIC = 1 V/100 Ω = 10 mA ; IL(max) = 250 mA, PR1 = 6,25 W', 'ΔIC = 1 V/100 Ω = 10 mA ; IL(max) = 250 mA, PR1 = 6.25 W')) + ex(tr('Floyd Bài 17', 'Floyd Problem 17'), tr('T = 100 μs, ton = 40 μs → 40 %', 'T = 100 μs, ton = 40 μs → 40 %')),
             K[2], tr('Giới hạn dòng, song song, xung (Floyd Bài 10–17)', 'Current limiting, shunt, switching (Floyd Problems 10–17)'), tr('Tất cả khớp đáp án sách (500 mA, 10 mA, 250 mA, 6,25 W, 40 %).', 'All match the book (500 mA, 10 mA, 250 mA, 6.25 W, 40 %).'))
    s11 = sl(ex(tr('Floyd Bài 21, 23', 'Floyd Problems 21, 23'), f'VOUT = 1,25 × 11 + 50 μA × 10 kΩ = {f(v21)} V; I = {f(v21/11e3*1e3,2)} mA'.replace('1,25', tr('1,25', '1.25'))) + ex(tr('Floyd Bài 25, 27', 'Floyd Problems 25, 27'), 'Rext = 2.8 Ω ; Rlimit = 0.35 Ω'),
             K[2], tr('IC ổn áp (Floyd Bài 20–27)', 'IC regulators (Floyd Problems 20–27)'), tr('LM317: 14,3 V và 1,3 mA đúng sách.', 'LM317: 14.3 V and 1.3 mA match the book.'))
    P.append(dict(title=tr('Ví dụ từ sách', 'Worked examples from the book'), bullets=[tr('Ổn áp nối tiếp', 'Series'), tr('Song song, xung', 'Shunt, switching'), tr('IC ổn áp', 'IC regulators')], slides=[s9, s10, s11]))
    s12 = sl(callout('warn', tr('Công suất toả nhiệt', 'Heat dissipation'), tr('Bộ ổn áp tuyến tính tiêu tán (VIN − VOUT)·IL: chọn VIN vừa đủ trên mức dropout và gắn tản nhiệt.', 'A linear regulator dissipates (VIN − VOUT)·IL: choose VIN just above dropout and add a heat sink.')),
             K[3], tr('Nhiệt là giới hạn chính', 'Heat is the main limit'), tr('Hiệu suất ≈ VOUT/VIN cho ổn áp tuyến tính.', 'Efficiency ≈ VOUT/VIN for a linear regulator.'))
    s13 = sl(ul([tr('Xung hiệu suất cao nhưng có gợn và nhiễu điện từ', 'Switching is efficient but produces ripple and EMI'), tr('Ổn áp song song luôn tiêu hao dòng ngay cả khi không tải', 'A shunt regulator always wastes current even with no load')]),
             K[3], tr('Chọn loại ổn áp', 'Choosing the regulator type'), tr('Chọn theo hiệu suất, nhiễu và độ phức tạp.', 'Choose by efficiency, noise and complexity.'))
    s14 = sl(ul([tr('Điện áp vào phải lớn hơn VOUT một khoảng dropout (khoảng 2 V cho 78XX, 1,5–2 V cho LM317)', 'VIN must exceed VOUT by the dropout voltage (≈ 2 V for 78XX, ≈ 1.5–2 V for LM317)'), tr('Cần tụ lọc ở ngõ vào và ngõ ra để tránh dao động', 'Input and output capacitors are needed to avoid oscillation')]),
             K[3], tr('Giới hạn thực tế', 'Practical limits'), tr('Giá trị dropout lấy từ datasheet của chính linh kiện.', 'Take the dropout figure from the part’s own datasheet.'))
    P.append(dict(title=tr('Sai lầm thường gặp', 'Common pitfalls'), bullets=[tr('Nhiệt', 'Heat'), tr('Chọn loại', 'Choosing a type'), tr('Dropout', 'Dropout')], slides=[s12, s13, s14]))
    s15 = sl(ul([tr('Minh hoạ: cấp nguồn ổn định cho mạch cảm biến và vi xử lý từ nguồn điện thay đổi của tàu bay', 'Illustrative: giving sensors and microprocessors a stable supply from a varying aircraft power bus'), tr('Minh hoạ: ổn áp xung giảm tổn hao nhiệt trong khoang thiết bị kín', 'Illustrative: switching regulators reduce heat in a sealed equipment bay')]),
             K[4], tr('Nguồn ổn định cho điện tử hàng không', 'Stable supplies for avionics electronics'), tr('Chỉ minh hoạ nguyên lý, không mô tả hệ thống cụ thể.', 'Illustrations of principle only, not a specific system.'))
    s16 = sl(table([tr('Đại lượng', 'Quantity'), tr('Công thức', 'Formula')], [['Line / Load', 'ΔVOUT/ΔVIN ; (VNL−VFL)/VFL'], [tr('Nối tiếp', 'Series'), '(1 + R2/R3)·VREF'], [tr('Giới hạn dòng', 'Current limit'), '0.7 V / R'], [tr('Xung', 'Switching'), 'VOUT ≈ duty × VIN'], ['LM317', '1.25(1 + R2/R1) + IADJ·R2']]),
             K[4], tr('Bảng công thức chương 17', 'Chapter 17 formula table'), tr('Năm dòng đủ cho phần tính toán của chương.', 'Five lines cover the chapter’s calculations.'))
    s17 = sl(ul([tr('Ổn áp = vòng hồi tiếp âm với tham chiếu', 'A regulator is a negative-feedback loop with a reference'), tr('Tuyến tính: êm nhưng nóng; xung: hiệu suất nhưng nhiễu', 'Linear: quiet but hot; switching: efficient but noisy'), tr('Module sau: PCB', 'Next module: PCBs')]),
             K[4], tr('Ba ý chính', 'Three take-aways'), tr('Hãy nhớ công thức 0,7 V/R cho mọi mạch giới hạn dòng.', 'Remember 0.7 V/R for every current-limiting circuit.').replace('0,7', tr('0,7', '0.7')))
    P.append(dict(title=tr('Ứng dụng và tổng kết', 'Applications and summary'), bullets=[tr('Nguồn điện tử hàng không (minh hoạ)', 'Avionics supplies (illustrative)'), tr('Bảng công thức', 'Formula table'), tr('Ba ý chính', 'Take-aways')], slides=[s15, s16, s17]))
    nt = '<h3>1. ' + tr('Nội dung chi tiết đối chiếu sách', 'Detailed content mapped to the books') + '</h3>' + ul([tr('Floyd §17–1 điều chỉnh; §17–2 ổn áp nối tiếp; §17–3 ổn áp song song; §17–4 ổn áp xung; §17–5 IC ổn áp (78XX, 79XX, LM317, LM337); §17–6 tăng dòng bằng transistor pass ngoài và giới hạn dòng.', 'Floyd §17–1 regulation; §17–2 series regulators; §17–3 shunt regulators; §17–4 switching regulators; §17–5 IC regulators (78XX, 79XX, LM317, LM337); §17–6 boosting current with an external pass transistor and current limiting.'), tr('Không có chương Jaeger tương ứng trong bản đồ đề cương.', 'No Jaeger chapter is mapped to this module in the syllabus map.')])
    nt += '<h3>2. ' + tr('Năm ví dụ có lời giải số', 'Five worked examples') + '</h3>' + ''.join([ex('1', 'Load regulation = (10 − 9.90)/9.90 × 100 % = 1.01 %'), ex('2', 'VOUT = (1 + 5.6/2.2) × 2.4 = 8.51 V'), ex('3', 'R4 = 0.7/0.25 = 2.8 Ω, P = 0.175 W'), ex('4', f'LM317: VOUT = 1.25 × 11 + 0.5 = {f(v21)} V'), ex('5', 'Rext = 0.7/0.25 = 2.8 Ω for IREG = 250 mA')])
    nt += '<h3>3. ' + tr('Bối cảnh lịch sử/lý thuyết', 'History and theory context') + '</h3><p>' + tr('Ổn áp IC ba chân (họ 78XX) làm cho việc cấp nguồn trở nên đơn giản; ổn áp xung thay thế dần ổn áp tuyến tính khi cần hiệu suất cao.', 'Three-terminal IC regulators (the 78XX family) made power supplies simple; switching regulators gradually replaced linear ones where efficiency matters.') + '</p>'
    nt += '<h3>4. ' + tr('Ca ứng dụng trên tàu bay (minh hoạ)', 'Aircraft case study (illustrative)') + '</h3><p>' + tr('Minh hoạ: nguồn ổn định cho điện tử hàng không từ thanh cái thay đổi. Không mô tả hệ thống cụ thể.', 'Illustrative: stable supplies for avionics from a varying bus. Not a specific system.') + '</p>'
    nt += '<h3>5. ' + tr('Bẫy khi làm bài thi', 'Exam pitfalls') + '</h3>' + ul([tr('Nhầm line regulation với load regulation.', 'Mixing line and load regulation.'), tr('Quên cộng IADJ·R2 trong LM317.', 'Forgetting IADJ·R2 in the LM317 formula.'), tr('Dùng VNL thay VFL ở mẫu số của load regulation.', 'Using VNL instead of VFL in the load-regulation denominator.'), tr('Nhầm 78XX (dương) với 79XX (âm).', 'Confusing 78XX (positive) with 79XX (negative).')])
    return dict(subtitle=tr('Line/load regulation, ổn áp nối tiếp, song song, xung, IC 78XX/79XX/LM317 và transistor pass ngoài (Floyd chương 17).', 'Line/load regulation, series, shunt and switching regulators, 78XX/79XX/LM317 ICs and external pass transistors (Floyd Chapter 17).'), time=tr('≈ 5 giờ', '≈ 5 h'),
                objectives=[tr('Tính line và load regulation', 'Compute line and load regulation'), tr('Phân tích ổn áp nối tiếp, song song, xung', 'Analyse series, shunt and switching regulators'), tr('Thiết kế mạch LM317 và giới hạn dòng', 'Design LM317 circuits and current limiting'), tr('Chọn IC 78XX/79XX và transistor pass ngoài', 'Choose 78XX/79XX ICs and external pass transistors')], parts=P, notes=nt)
